&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;2,2,0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Engage with global customers to gather feedback, identify market opportunities, analyze competition, and anticipate emerging trends&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;2,3,0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Deliver an intuitive administrator experience that simplifies complex security operations with actionable, data-driven insights&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;3&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;3&quot; data-index-in-node=&quot;0&quot;&gt;Who You Are (Success Profile)&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
