&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;6,2,0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Track record of building effective cross-functional relationships, specifically with engineering teams&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;6,3,0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience working directly with customers on security feature requirements and feedback&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;6,4,0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Bachelor’s or Master’s degree in Computer Science, Engineering, or a related field&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
